package com.trimtime.availability;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/barber/availability") @PreAuthorize("hasRole('BARBER')") public class AvailabilityController {private final AvailabilityService service; public AvailabilityController(AvailabilityService service){this.service=service;} private Long current(){return ((com.trimtime.identity.SessionAuthenticationFilter.UserPrincipal)SecurityContextHolder.getContext().getAuthentication().getPrincipal()).id();}
 @GetMapping("/hours") public List<AvailabilityDtos.HourResponse> hours(@RequestParam(required=false) java.time.LocalDate weekStartDate){var week=weekStartDate==null?java.time.LocalDate.now():weekStartDate;return service.getHours(current(),week).stream().map(AvailabilityDtos.HourResponse::from).toList();} @PutMapping("/hours") public AvailabilityDtos.HourResponse hour(@Valid @RequestBody AvailabilityDtos.HourRequest input){return AvailabilityDtos.HourResponse.from(service.saveHour(current(),input));} @PutMapping("/hours/bulk") public List<AvailabilityDtos.HourResponse> bulkHours(@Valid @RequestBody AvailabilityDtos.BulkHourRequest input){return service.saveHours(current(),input).stream().map(AvailabilityDtos.HourResponse::from).toList();}
 @GetMapping("/days-off") public List<AvailabilityDtos.DayOffResponse> days(){return service.getDays(current()).stream().map(AvailabilityDtos.DayOffResponse::from).toList();} @PostMapping("/days-off") public ResponseEntity<AvailabilityDtos.DayOffResponse> add(@Valid @RequestBody AvailabilityDtos.DayOffRequest input){return ResponseEntity.status(HttpStatus.CREATED).body(AvailabilityDtos.DayOffResponse.from(service.addDay(current(),input)));} @DeleteMapping("/days-off/{id}") public ResponseEntity<Void> remove(@PathVariable Long id){service.removeDay(current(),id);return ResponseEntity.noContent().build();}
}
